import http.server,sys,os
class H(http.server.SimpleHTTPRequestHandler):
    def end_headers(self):
        p=self.path.split('?')[0]
        if p.endswith('.unityweb'):
            self.send_header('Content-Encoding','gzip')
        super().end_headers()
    def guess_type(self,p):
        if p.endswith('.wasm.unityweb'): return 'application/wasm'
        if p.endswith('.js.unityweb'): return 'application/javascript'
        return super().guess_type(p)
    def log_message(self,*a): pass
os.chdir(sys.argv[2]); http.server.ThreadingHTTPServer(('127.0.0.1',int(sys.argv[1])),H).serve_forever()
